const rand=(n)=>{let x=Math.sin(n*127.1+311.7)*43758.5453;return x-Math.floor(x)};
function path(d,fill,stroke='#112d28',lw=2){const q=new Path2D(d);if(fill){ctx.fillStyle=fill;ctx.fill(q)}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=lw;ctx.stroke(q)}}
function line(d,color,w=1){path(d,null,color,w)}
function resize(){const r=canvas.getBoundingClientRect();width=r.width;height=r.height;canvas.width=width*Math.min(devicePixelRatio,2);canvas.height=height*Math.min(devicePixelRatio,2);const portrait=width/height<.8;const viewWidth=portrait?640:W;const centerX=portrait?465:W/2;scale=Math.min(width/viewWidth,height/H);ox=width/2-centerX*scale;oy=(height-H*scale)/2}addEventListener('resize',resize);resize();
function leaf(x,y,size,angle,palette,detail=true){ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.scale(size,size);let g=ctx.createLinearGradient(0,-80,0,55);g.addColorStop(0,palette[0]);g.addColorStop(.55,palette[1]);g.addColorStop(1,palette[2]);path('M-140 7 C-102-23-114-54-57-59 C-33-87 7-77 38-54 C82-50 115-15 150 1 C110 18 91 51 41 44 C5 65-34 49-62 38 C-104 40-120 17-140 7Z',g,palette[3],2.3);line('M-139 7 Q-52-9 150 1',palette[4],2);if(detail){for(let i=0;i<8;i++){let x=-108+i*29;let amp=30+30*Math.sin(i/8*Math.PI);line(`M${x} 1 Q${x+12} ${-amp*.5} ${x+9} ${-amp}`,palette[4],.85);line(`M${x} 1 Q${x+14} 24 ${x+23} ${amp*.65}`,palette[4],.8)}line('M-105-29 Q-70-59-47-52 M-18-67 Q8-65 28-51 M64-34 Q97-17 111-11',palette[5],1.5);for(let i=0;i<30;i++){ctx.globalAlpha=.15;ctx.fillStyle=palette[4];ctx.beginPath();ctx.ellipse(-110+rand(i+7)*230,-40+rand(i+33)*72,1,rand(i)*3,0,0,7);ctx.fill()}ctx.globalAlpha=1}ctx.restore()}
function background(){let g=ctx.createLinearGradient(0,0,900,800);g.addColorStop(0,'#142b30');g.addColorStop(.48,'#426052');g.addColorStop(1,'#152f2c');ctx.fillStyle=g;ctx.fillRect(-1000,-1000,3000,3000);let glow=ctx.createRadialGradient(570,250,20,570,250,520);glow.addColorStop(0,'#bfca9257');glow.addColorStop(1,'#b3bd7d00');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H);
ctx.save();ctx.globalAlpha=.17;for(let i=0;i<12;i++){let x=rand(i+12)*1100;line(`M${x} 900 C${x-150} 550 ${x+160} 300 ${x-10} -50`,'#0a282a',20+rand(i)*40);for(let j=0;j<3;j++)leaf(x+(j%2?65:-60),100+j*230+rand(i)*90,.7,rand(i+j)*2,['#689078','#476d60','#2f524c','#34584e','#8bab85','#bed0a4'],false)}ctx.restore();
// A towering leaf wall: veins remain subordinate to the traversable silhouettes.
ctx.save();ctx.globalAlpha=.24;ctx.translate(510,470);ctx.rotate(-.15);ctx.scale(2.1,4.1);leaf(0,0,1,-Math.PI/2,['#637f59','#3c6450','#254f43','#254d43','#9bac73','#b5c58c']);ctx.restore();
line('M450 860 C650 720 380 566 490 418 C610 275 440 173 530-60','#173f35',19);line('M447 860 C645 720 374 567 485 418 C605 275 435 173 525-60','#67815a',4);for(let i=0;i<4;i++){const l=leaves[i];line(`M485 ${l.y+80} Q${l.x-50} ${l.y+55} ${l.x} ${l.y}`,'#193d2d',12);line(`M485 ${l.y+80} Q${l.x-50} ${l.y+55} ${l.x} ${l.y}`,'#7b9160',3)}
for(let i=0;i<55;i++){let x=(rand(i)*1050+Math.sin(time*.13+i)*14),y=(rand(i+79)*850-time*(2+rand(i)*7))%850;ctx.globalAlpha=.15+rand(i)*.32;ctx.fillStyle='#d2db99';ctx.beginPath();ctx.arc(x,y<0?y+850:y,.6+rand(i+9)*1.5,0,7);ctx.fill()}ctx.globalAlpha=1;
}
function character(){ctx.save();const gripping=mode==='grab';const progress=gripping?Math.max(0,Math.min(1,1-phase/.42)):1;const ease=progress*progress*(3-2*progress);const drop=gripping?42*(1-ease):0;ctx.translate(p.x,p.y+drop);ctx.scale(p.face,1);let crouch=mode==='aim'?.16:mode==='anticipate'?.22:0;ctx.scale(1+crouch*.5,1-crouch);let flying=mode==='air',tilt=flying?p.vx*.00065:Math.sin(time*1.7)*.018;ctx.rotate(tilt);let fl=flying?Math.sin(time*20)*5:Math.sin(time*3)*2;
// A borrowed sewing needle, bundled seed pack, soft cap — not Hornet's mask or horns.
line('M-24-3 L24-62','#101f23',4);line('M-24-3 L24-62','#c9cfb8',1.2);ctx.strokeStyle='#c9cfb8';ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(23,-61,2,4,.65,0,7);ctx.stroke();
path('M-11-42 Q-31-44-29-24 Q-24-12-9-20Z','#aa9470','#243730',2);line('M-23-41 Q-17-30-25-21 M-28-31 L-10-29','#685b45',1.4);
const feet=flying?'M-5-17 Q-17-10-21-5 L-13-3 Q-7-6-1-11 M6-17 Q16-7 19-13 L23-11 Q20-3 16-2 L4-8':'M-6-16 Q-9-9-8-2 L-15 0 L-4 1 L0-13 M6-17 L10-3 L17 0 L6 0 L1-12';path(feet,'#182725','#101f22',2);
path(`M-9-43 Q-15-31 ${-22-fl}-${flying?'17':'10'} Q-8-16-2-10 Q6-19 18-13 Q11-31 8-43Z`,'#a8473d','#251f26',2.3);path(`M-5-39 Q-7-23 ${-17-fl}-15 L-3-20 L1-13 L7-26 L5-41Z`,'#cb6650',null);line('M-5-35 Q-2-25-3-19','#ed9270',1.1);
let hand=flying?'M5-38 Q17-40 21-51':'M5-37 Q18-31 14-21';if(!gripping){line(hand,'#212b28',5);line(hand,'#b5a57f',2.4)}if(gripping){for(const side of [-1,1]){const hx=side*16,hy=-drop;const arm=`M${side*8}-35 Q${side*24} ${-17-drop*.3} ${hx} ${hy}`;line(arm,'#1c2c27',5);line(arm,'#b8a47b',2.5);line(`M${hx-3} ${hy} L${hx+4} ${hy-1}`,'#e5d0a0',3)}}if(!flying&&!gripping){line('M-10-36 Q-23-23-17-4','#23342d',4);line('M-17-4 L-12-1','#d3c1a0',3)}
path('M-10-49 Q-13-61-3-65 Q11-67 15-55 L12-42 Q1-35-9-43Z','#d9c59a','#25332d',2);path('M-13-49 Q-18-61-4-70 Q5-76 15-66 Q22-66 23-59 L13-57 Q4-64-4-54Z','#526c58','#203b31',2);line('M-13-54 Q-2-69 14-63','#90a181',1);ctx.fillStyle='#243532';ctx.beginPath();ctx.ellipse(8,-50,1.8,2.2,0,0,7);ctx.fill();line('M11-45 L15-46','#8c7253',1);path('M-8-42 Q5-47 12-40 L8-35 Q-4-37-10-36Z','#ce6a4e','#422a2a',1);ctx.restore()}
function render(){ctx.setTransform(canvas.width/width,0,0,canvas.height/height,0,0);ctx.clearRect(0,0,width,height);ctx.translate(ox,oy);ctx.scale(scale,scale);background();for(let i=0;i<leaves.length;i++){const l=leaves[i];let elapsed=time-l.hit,sway=elapsed>=0&&elapsed<3?Math.sin(elapsed*15)*.055*Math.exp(-elapsed*2):0;leaf(l.x,l.y+9,1,l.a+sway,['#779566','#496d45','#244637','#172e29','#a8b78088','#c2ca91']);ctx.fillStyle='#e2d5a4';ctx.globalAlpha=i===leafIndex+1?.8:.3;ctx.beginPath();ctx.arc(l.x,l.y-6,2.6,0,7);ctx.fill();ctx.globalAlpha=1}
for(const t of trail){ctx.globalAlpha=t.life*.14;ctx.fillStyle='#edd1a1';ctx.beginPath();ctx.ellipse(t.x,t.y-30,6,20,-.4*p.face,0,7);ctx.fill()}ctx.globalAlpha=1;character();for(const m of motes){ctx.globalAlpha=m.life;ctx.fillStyle='#d6ce99';ctx.beginPath();ctx.arc(m.x,m.y,1.3,0,7);ctx.fill()}ctx.globalAlpha=1;
if(drag){const v=velocity(drag);ctx.setLineDash([2,9]);ctx.lineWidth=1.5;ctx.strokeStyle='#e0d7a1aa';ctx.beginPath();ctx.moveTo(p.x,p.y-30);for(let t=.05;t<.65;t+=.05)ctx.lineTo(p.x+v.x*t,p.y-30+v.y*t+450*t*t);ctx.stroke();ctx.setLineDash([]);ctx.strokeStyle='#d6c69a88';ctx.beginPath();ctx.moveTo(drag.sx,drag.sy);ctx.lineTo(drag.x,drag.y);ctx.stroke();ctx.beginPath();ctx.arc(drag.x,drag.y,9,0,7);ctx.stroke()}
// Near-field silhouettes frame the illustrated world.
ctx.save();ctx.globalAlpha=.9;leaf(-35,710,1.9,-.8,['#0c2424','#102b27','#0b211f','#0b211f','#244137','#274638']);leaf(1020,460,1.7,.7,['#0b2526','#13342d','#0a231f','#0a211f','#2a4435','#2b4938']);leaf(930,860,2,-.4,['#0b2626','#112f2a','#091e1e','#091f1d','#244438','#2c4939']);ctx.restore();let vignette=ctx.createRadialGradient(500,400,220,500,400,650);vignette.addColorStop(0,'#001b1800');vignette.addColorStop(1,'#04191d99');ctx.fillStyle=vignette;ctx.fillRect(-ox/scale,-oy/scale,width/scale,height/scale)}
function velocity(d){const dx=d.sx-d.x,dy=Math.max(0,d.y-d.sy);return{x:Math.max(-450,Math.min(450,dx*4)),y:-Math.min(780,dy*4.5)}}
function launch(v){pending=v;mode='anticipate';phase=.14;p.face=v.x>=0?1:-1;drag=null;statusEl.textContent='蓄势';}
function reset(){p={x:340,y:664,vx:0,vy:0,face:1};leafIndex=0;mode='idle';drag=null;auto=false;trail=[];statusEl.textContent='按住 · 向下拉 · 松手跃起';document.querySelector('#demo').textContent='观看动作'}
function demo(){reset();auto=true;nextAuto=time+.5;document.querySelector('#demo').textContent='演示中 · 点击停止'}
function update(dt){if(auto&&mode==='idle'&&time>nextAuto){if(leafIndex===3){auto=false;document.querySelector('#demo').textContent='再次观看';statusEl.textContent='抵达晨光 · 四片叶的旅程'}else{const target=leaves[leafIndex+1],duration=.72;launch({x:(target.x-p.x)/duration,y:(target.y-p.y-450*duration*duration)/duration})}}if(mode==='anticipate'){phase-=dt;if(phase<=0){mode='air';p.vx=pending.x;p.vy=pending.y;statusEl.textContent='跃出';leaves[leafIndex].hit=time}}else if(mode==='grab'){phase-=dt;if(phase<=0){mode='idle';nextAuto=time+.8;statusEl.textContent=leafIndex===3?'抵达晨光 · 重新攀爬，再试一次':'抓稳了 · 向下一片叶跃去'}}else if(mode==='air'){const prevY=p.y;p.x+=p.vx*dt;p.y+=p.vy*dt+450*dt*dt;p.vy+=900*dt;trail.push({x:p.x,y:p.y,life:1});if(p.vy>0){for(let i=0;i<leaves.length;i++){let l=leaves[i];if(prevY<=l.y&&p.y>=l.y&&Math.abs(p.x-l.x)<105){p.y=l.y;p.vx=p.vy=0;leafIndex=i;mode='grab';phase=.42;l.hit=time;statusEl.textContent='抓停';for(let j=0;j<14;j++)motes.push({x:p.x,y:p.y,vx:(rand(j+time)-.5)*100,vy:-20-rand(j)*50,life:1});break}}}if(p.y>850||p.x<-60||p.x>1060){let l=leaves[leafIndex];p.x=l.x;p.y=l.y;p.vx=p.vy=0;mode='grab';phase=.3;statusEl.textContent='回到上一片叶 · 再试一次'}}for(const t of trail)t.life-=dt*4;trail=trail.filter(t=>t.life>0);for(const m of motes){m.x+=m.vx*dt;m.y+=m.vy*dt;m.vy+=70*dt;m.life-=dt}motes=motes.filter(m=>m.life>0)}
function point(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left-ox)/scale,y:(e.clientY-r.top-oy)/scale}}
function cancelAim(){drag=null;if(mode==='aim'){mode='idle';statusEl.textContent='按住 · 向下拉 · 松手跃起'}}
canvas.addEventListener('pointerdown',e=>{if(drag||e.isPrimary===false||e.button!==0||mode!=='idle')return;auto=false;document.querySelector('#demo').textContent='观看动作';const q=point(e);drag={sx:q.x,sy:q.y,x:q.x,y:q.y,id:e.pointerId};mode='aim';canvas.setPointerCapture(e.pointerId)});
canvas.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;Object.assign(drag,point(e));let v=velocity(drag);p.face=v.x>=0?1:-1;statusEl.textContent=`蓄力 ${Math.round(-v.y/780*100)}% · 松手跃起`});
canvas.addEventListener('pointerup',e=>{if(!drag||e.pointerId!==drag.id)return;Object.assign(drag,point(e));const v=velocity(drag);if(v.y>-90){drag=null;mode='idle';statusEl.textContent='向下拉得更远一些'}else launch(v)});
canvas.addEventListener('pointercancel',cancelAim);canvas.addEventListener('lostpointercapture',cancelAim);addEventListener('blur',cancelAim);addEventListener('resize',cancelAim);document.querySelector('#reset').onclick=reset;document.querySelector('#demo').onclick=()=>auto?reset():demo();addEventListener('keydown',e=>{if(e.code==='Space'&&!['BUTTON','INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)&&!e.target.isContentEditable){e.preventDefault();demo()}if(e.code==='KeyR'&&!['BUTTON','INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)&&!e.target.isContentEditable)reset()});
function frame(t){const dt=Math.min((t-last)/1000,.035);last=t;time+=dt;update(dt);render();requestAnimationFrame(frame)}requestAnimationFrame(frame);
window.inkStudy={getState:()=>({mode,leafIndex,auto,p:{...p}}),demo,reset,velocity};
